#include <map>
#include <string>

int main() {
    std::map<std::string, double> stocks = {{"A", 100.0}};

    auto pos = stocks.begin();

    // 1. Accessing key and value
    std::string key = pos->first; 
    double value = pos->second;

    // 2. Modifying the value (Allowed)
    pos->second *= 2; // Price doubled to 200.0

    // 3. Attempting to modify the key (Compiler Error)
    // pos->first = "NewKey"; 
    // Error: assignment of read-only member 'std::pair<const K, V>::first'
}
